import { Injectable, Logger } from '@nestjs/common';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { config } from '../config/config';

/**
 * Reference data GENERATED by Python (`pfa export-reference`), never re-declared here.
 *
 * That is the whole point: a tax ceiling or a country alias has exactly one definition, in
 * `pfa/rules.py` and `pfa/taxonomy.py`, carrying its own VERIFIED_ON date. Copying them into
 * TypeScript would guarantee they drift.
 */
@Injectable()
export class ReferenceService {
  private cache = new Map<string, any>();
  private readonly log = new Logger('reference');

  private load<T>(name: string): T {
    if (!this.cache.has(name)) {
      const path = join(config.generatedDir, name);
      try {
        this.cache.set(name, JSON.parse(readFileSync(path, 'utf-8')));
      } catch (e) {
        this.log.warn(`${path} unreadable — run \`python3 -m pfa export-reference\``);
        this.cache.set(name, {});
      }
    }
    return this.cache.get(name) as T;
  }

  get rules() { return this.load<Record<string, any>>('rules.json'); }
  get taxonomy() { return this.load<Record<string, any>>('taxonomy.json'); }
  get targets() { return this.load<Record<string, Record<string, number>>>('targets.json'); }
  get verifiedOn(): string { return this.rules['VERIFIED_ON'] ?? 'unknown'; }

  /** profile/manual_inputs.json: facts Finary cannot know. Explains figures, never computes one. */
  private get manual() { return this.load<Record<string, any>>('manual.json'); }
  get closedAccounts(): Record<string, any> { return this.manual['closed_accounts'] ?? {}; }
  get userName(): string | null { return (this.manual['display_name'] as string | undefined) ?? null; }
  get receivables(): Record<string, any>[] { return this.manual['receivables'] ?? []; }
  /** profile/etf_proxies.json: which fund borrows its constituents from which ETF. */
  get etfProxies(): Record<string, any> { return this.load<Record<string, any>>('etf_proxies.json')['funds'] ?? {}; }
  get glossary(): Record<string, any> { return this.load<Record<string, any>>('glossary.json')['metrics'] ?? {}; }
  get learningPrompts(): any[] { return this.load<Record<string, any>>('learning_prompts.json')['prompts'] ?? []; }
  get accountFees(): Record<string, number> { return this.manual['account_fees'] ?? {}; }
}
